// Design tokens for the 5 Slides in 5 Minutes library.
// Slide stage: 13.333in x 7.5in (PowerPoint LAYOUT_WIDE). All coordinates are inches.

const STAGE = { w: 13.333, h: 7.5, margin: 0.75 };

// Font roles. PowerPoint uses Bahnschrift (system DIN, ships with Windows) so Eric can
// edit on any machine; HTML embeds the Baylor DIN Pro files from Baylor_Fonts.
const FONTS = {
  body:      { pptx: "Bahnschrift",                   css: "'DIN Pro', 'Bahnschrift', sans-serif", weight: 400 },
  light:     { pptx: "Bahnschrift Light",             css: "'DIN Pro', 'Bahnschrift', sans-serif", weight: 300 },
  medium:    { pptx: "Bahnschrift SemiBold",          css: "'DIN Pro', 'Bahnschrift', sans-serif", weight: 500 },
