  condBold:  { pptx: "Bahnschrift SemiBold Condensed", css: "'DIN Pro Condensed', 'Bahnschrift Condensed', sans-serif", weight: 700 },
};

// Palettes. Each has a dark mode (slides 1, 3, 5) and a light mode (slides 2, 4).
// Roles: bg ground, ink primary text, muted secondary text (>=4.5:1 on bg),
// accent = the one emphasis colour (text-safe on its own ground), shape = data/graphic
// fill (>=3:1 on bg), soft = quiet secondary fill, rule = hairlines.
const PALETTES = {
  forest: {
    name: "Forest and gold",
    dark:  { bg: "0B2A1F", ink: "F4F2EC", muted: "AFD2C0", accent: "FFB81C", shape: "FFB81C", soft: "16402F", rule: "2E5C49" },
    light: { bg: "F4F2EC", ink: "0B2A1F", muted: "4E5150", accent: "154734", shape: "154734", soft: "E2DED2", rule: "CFCABB" },
  },
  baylor: {
    name: "Baylor green and white",
    dark:  { bg: "154734", ink: "FFFFFF", muted: "CFE3D7", accent: "FFB81C", shape: "FFB81C", soft: "1F5A43", rule: "3A7559" },
    light: { bg: "FFFFFF", ink: "154734", muted: "4E5150", accent: "154734", shape: "154734", soft: "EDF2EE", rule: "D7E0DA" },
  },
  charcoal: {
    name: "Charcoal and stone",
    dark:  { bg: "1E1F1F", ink: "F2F0EA", muted: "BDB8AA", accent: "FFB81C", shape: "FFB81C", soft: "2C2D2D", rule: "4A4B4A" },
    light: { bg: "ECE9DE", ink: "1E1F1F", muted: "55554F", accent: "154734", shape: "154734", soft: "DDD9CB", rule: "C9C4B4" },
  },
  mint: {
    name: "Deep green and mint",
    dark:  { bg: "07211A", ink: "E4F0E9", muted: "93B3A3", accent: "AFD2C0", shape: "AFD2C0", soft: "0F3328", rule: "1E4D3D" },
    light: { bg: "E4F0E9", ink: "07211A", muted: "3F5A4D", accent: "1E6349", shape: "1E6349", soft: "CFE3D7", rule: "B5D0C1" },
  },
  gold: {
    name: "Gold field",
    dark:  { bg: "07211A", ink: "F4F2EC", muted: "AFD2C0", accent: "FFB81C", shape: "FFB81C", soft: "16402F", rule: "2E5C49" },
    light: { bg: "FFB81C", ink: "0B2A1F", muted: "3B3410", accent: "0B2A1F", shape: "0B2A1F", soft: "F5A800", rule: "D99A0B" },
  },
  slate: {
    name: "Slate green and pale gold",
    dark:  { bg: "26352F", ink: "F4F2EC", muted: "C3CEC7", accent: "F2CF7A", shape: "F2CF7A", soft: "31433B", rule: "4C6157" },
    light: { bg: "EEF0EB", ink: "26352F", muted: "4F5A54", accent: "26352F", shape: "4C6157", soft: "DEE3DC", rule: "C7CEC6" },
  },
  night: {
    name: "Night and signal gold",
    dark:  { bg: "0F1715", ink: "FFFFFF", muted: "A9B6B0", accent: "FFB81C", shape: "FFB81C", soft: "1A2522", rule: "33423D" },
    light: { bg: "FAFAF7", ink: "0F1715", muted: "50534F", accent: "24704F", shape: "24704F", soft: "ECEEE8", rule: "D9DCD4" },
  },
