    dark:  { bg: "1E6349", ink: "FFFFFF", muted: "DCEDE3", accent: "FFD679", shape: "FFD679", soft: "267052", rule: "4A8B6E" },
    light: { bg: "EEF2EC", ink: "173F2F", muted: "45574D", accent: "1E6349", shape: "1E6349", soft: "DCE5DA", rule: "C3D0C3" },
  },
  sand: {
    name: "Ink green and sand",
    dark:  { bg: "103827", ink: "F4F2EC", muted: "B9CFC2", accent: "F4F2EC", shape: "E8D9B5", soft: "1A4733", rule: "336650" },
    light: { bg: "EFE8D8", ink: "103827", muted: "524B3B", accent: "7A6420", shape: "103827", soft: "E2D8C2", rule: "CFC3A8" },
  },
  paper: {
    name: "Paper and antique gold",
    dark:  { bg: "1A2E26", ink: "F4F2EC", muted: "B5C7BD", accent: "E3C26A", shape: "E3C26A", soft: "243B31", rule: "3F5A4D" },
    light: { bg: "FBF9F3", ink: "1A2E26", muted: "4E5150", accent: "7A6420", shape: "1A2E26", soft: "EFEBDF", rule: "DCD6C6" },
  },
};

// Slide roles in fixed series order, with the series' dark/light alternation.
const ROLES = [
  { id: "hook",        name: "Hook",                mode: "dark" },
  { id: "problem",     name: "Problem",             mode: "light" },
  { id: "insight",     name: "Insight",             mode: "dark" },
  { id: "application", name: "Application",         mode: "light" },
  { id: "takeaway",    name: "Takeaway",            mode: "dark" },
];

module.exports = { STAGE, FONTS, PALETTES, ROLES };
// Series spine drawn on every slide: running head, footer, and the 5-frame rail that
// marks where the talk stands. Identical position on all 200 slides.

const { STAGE } = require("./tokens");

function chrome(deck, index, scene) {
  const P = scene.P;
  const M = STAGE.margin;
  const items = [];
  const text = (x, y, w, h, t, o) => items.push({
    t: "text", x, y, w, h, runs: [{ t }], font: o.font, size: o.size, color: o.color,
    align: o.align || "left", valign: "middle", lineH: 1, tracking: o.tracking || 0, caps: !!o.caps, italic: false, role: "chrome",
  });

  text(M, 0.42, 5, 0.3, "5 Slides · 5 Minutes", { font: "cond", size: 11, color: P.muted, tracking: 2, caps: true });
  text(STAGE.w - M - 6.5, 0.42, 6.5, 0.3, deck.meta.title, { font: "cond", size: 11, color: P.muted, tracking: 1, caps: true, align: "right" });

  text(M, 6.86, 6, 0.3, "Baylor Athletics · Applied Performance", { font: "body", size: 10.5, color: P.muted });

  // Rail: five frames, current one filled with the accent.
  const fw = 0.34, gap = 0.08, fh = 0.06;
  const x0 = STAGE.w - M - (5 * fw + 4 * gap);
  for (let k = 0; k < 5; k++) {
    items.push({ t: "rect", x: x0 + k * (fw + gap), y: 6.98, w: fw, h: fh, fill: k === index ? P.accent : P.rule, line: null, lineW: 1, opacity: 1 });
  }
  return items;
}

module.exports = { chrome };
// Scene kit: deck.js files draw each slide with these primitives. A scene is a flat,
// ordered list of items in inch coordinates; render-pptx.js and render-html.js both
// read the same list, so the PowerPoint and HTML versions cannot drift apart.

const { STAGE, PALETTES, ROLES } = require("./tokens");

const M = STAGE.margin;
// Content box between the running head and the footer.
const AREA = { x: M, y: 1.15, w: STAGE.w - 2 * M, h: 5.45, right: STAGE.w - M, bottom: 6.6 };

class Scene {
  constructor(mode, palette) {
    this.mode = mode;
    this.P = palette[mode];
    this.items = [];
    this.refs = new Set();
  }

  // Colour tokens ("ink", "accent", ...) resolve against the slide's palette mode;
  // anything else is taken as a hex string.
  c(v) {
    if (v == null) return null;
    return this.P[v] || String(v).replace("#", "").toUpperCase();
  }

  rect(x, y, w, h, o = {}) {
    this.items.push({ t: "rect", x, y, w, h, fill: this.c(o.fill), line: this.c(o.line), lineW: o.lineW || 1, opacity: o.opacity ?? 1, dash: o.dash });
    return this;
  }

  ellipse(x, y, w, h, o = {}) {
    this.items.push({ t: "ellipse", x, y, w, h, fill: this.c(o.fill), line: this.c(o.line), lineW: o.lineW || 1, opacity: o.opacity ?? 1 });
    return this;
  }

  circle(cx, cy, r, o = {}) { return this.ellipse(cx - r, cy - r, 2 * r, 2 * r, o); }

  line(x1, y1, x2, y2, o = {}) {
