// Render a built deck to an editable PowerPoint file: native text boxes and shapes only.

const PptxGenJS = require("pptxgenjs");
const { FONTS, STAGE } = require("./tokens");
const { chrome } = require("./chrome");
const { smoothToBeziers } = require("./geometry");

function renderPptx(deck, outPath) {
  const pptx = new PptxGenJS();
  pptx.layout = "LAYOUT_WIDE";
  pptx.author = "Eric Rash, Applied Performance";
  pptx.company = "Baylor Athletics";
  pptx.title = `${deck.meta.title} · 5 Slides in 5 Minutes`;

  deck.slides.forEach((sl, i) => {
    const s = pptx.addSlide();
    s.background = { color: sl.scene.P.bg };
    const items = [...sl.scene.items, ...chrome(deck, i, sl.scene)];
    for (const it of items) draw(pptx, s, it);
    s.addNotes(notesText(deck, sl, i));
  });
  return pptx.writeFile({ fileName: outPath });
}

function notesText(deck, sl, i) {
  const t = sl.time ? ` (~${sl.time}s)` : "";
  return `${i + 1}. ${sl.roleName}${t}\n\n${sl.notes || ""}`;
}

function fill(color, opacity = 1) {
  if (!color) return { type: "none" };
  return { color, transparency: Math.round((1 - opacity) * 100) };
}

function draw(pptx, s, it) {
  switch (it.t) {
    case "rect":
    case "ellipse":
      s.addShape(it.t === "rect" ? pptx.ShapeType.rect : pptx.ShapeType.ellipse, {
        x: it.x, y: it.y, w: it.w, h: it.h,
        fill: fill(it.fill, it.opacity),
        line: it.line ? { color: it.line, width: it.lineW, dashType: it.dash ? "dash" : "solid" } : { type: "none" },
      });
      break;

    case "line": {
      let { x1, y1, x2, y2 } = it;
      let begin = it.arrow === "both" || it.arrow === "start" ? "triangle" : "none";
      let end = it.arrow === "both" || it.arrow === "end" ? "triangle" : "none";
      // PowerPoint lines run from the box's top-left; normalise so x1 <= x2.
      if (x2 < x1 || (x2 === x1 && y2 < y1)) { [x1, x2] = [x2, x1]; [y1, y2] = [y2, y1]; [begin, end] = [end, begin]; }
      s.addShape(pptx.ShapeType.line, {
        x: x1, y: Math.min(y1, y2), w: Math.max(x2 - x1, 0.0001), h: Math.max(Math.abs(y2 - y1), 0.0001),
        flipV: y2 < y1,
        line: { color: it.color, width: it.w, dashType: it.dash ? "dash" : "solid", beginArrowType: begin, endArrowType: end },
      });
      break;
    }

    case "arc": {
      // Kit angles: 0 = 12 o'clock clockwise. PowerPoint: 0 = 3 o'clock clockwise.
      const norm = a => ((Math.round(a - 90) % 360) + 360) % 360;
      s.addShape(pptx.ShapeType.blockArc, {
        x: it.cx - it.r, y: it.cy - it.r, w: 2 * it.r, h: 2 * it.r,
        angleRange: [norm(it.start), norm(it.end)],
